1	import * as crypto from "node:crypto";
2	import * as fs from "node:fs";
3	import * as path from "node:path";
4	
5	export interface BlobMeta {
6	  key: string;
7	  size: number;
8	  sha256: string;
9	  modified_at: string;
10	}
11	
12	export interface PutResult {
13	  key: string;
14	  sha256: string;
15	  size: number;
16	}
17	
18	const TMP_DIR_NAME = ".syncbox-tmp";
19	const MAX_SEGMENT_BYTES = 255;
20	
21	/** Decodes a raw (still percent-encoded) path tail, or null if malformed. */
22	export function decodeKey(rawTail: string): string | null {
23	  try {
24	    return decodeURIComponent(rawTail);
25	  } catch {
26	    return null;
27	  }
28	}
29	
30	/**
31	 * Rejects anything that isn't a clean relative POSIX path: empty/absolute
32	 * paths, `.`/`..` segments, path separators embedded via encoding tricks,
33	 * bytes that can't round-trip as a UTF-8 filename (e.g. lone surrogates),
34	 * NUL, and segments too long for the filesystem.
35	 *
36	 * This is the first line of defense and rejects everything realistic on
37	 * its own. `resolveStorePath` below is a second, independent check applied
38	 * at actual filesystem-path construction time, so a bug here can't turn
39	 * into an escape.
40	 */
41	export function validateKey(key: string): boolean {
42	  if (key.length === 0) return false;
43	  if (key.includes("\0")) return false;
44	  if (Buffer.from(key, "utf8").toString("utf8") !== key) return false;
45	
46	  const segments = key.split("/");
47	  for (const segment of segments) {
48	    if (segment.length === 0) return false;
49	    if (segment === "." || segment === "..") return false;
50	    if (Buffer.byteLength(segment, "utf8") > MAX_SEGMENT_BYTES) return false;
51	  }
52	  return true;
53	}
54	
55	/**
56	 * Resolves a key to an absolute path on disk and asserts it lands strictly
57	 * inside dataDir. Independent of validateKey's segment-based checks: relies
58	 * only on Node's own path resolution (path.resolve collapses `.`/`..` and
59	 * normalizes separators), so it holds even if a key somehow reached this
60	 * point without going through validateKey first.
61	 */
62	function resolveStorePath(dataDir: string, key: string): string {
63	  const root = path.resolve(dataDir);
64	  const resolved = path.resolve(root, key);
65	  const rootWithSep = root.endsWith(path.sep) ? root : root + path.sep;
66	
67	  if (!resolved.startsWith(rootWithSep)) {
68	    throw new Error(`key resolves outside the data directory: ${key}`);
69	  }
70	  return resolved;
71	}
72	
73	/** Writes content under dataDir atomically (temp file + rename) and returns its metadata. */
74	export function putBlob(
75	  dataDir: string,
76	  key: string,
77	  content: Buffer
78	): PutResult {
79	  const destPath = resolveStorePath(dataDir, key);
80	  const tmpDir = path.join(dataDir, TMP_DIR_NAME);
81	
82	  fs.mkdirSync(tmpDir, { recursive: true });
83	  fs.mkdirSync(path.dirname(destPath), { recursive: true });
84	
85	  const tmpPath = path.join(
86	    tmpDir,
87	    `${crypto.randomBytes(16).toString("hex")}.tmp`
88	  );
89	  fs.writeFileSync(tmpPath, content);
90	  try {
91	    fs.renameSync(tmpPath, destPath);
92	  } catch (err) {
93	    fs.rmSync(tmpPath, { force: true });
94	    throw err;
95	  }
96	
97	  return {
98	    key,
99	    sha256: crypto.createHash("sha256").update(content).digest("hex"),
100	    size: content.length,
101	  };
102	}
103	
104	/** Reads a stored blob's content, or null if no blob exists at that key. */
105	export function getBlob(dataDir: string, key: string): Buffer | null {
106	  const srcPath = resolveStorePath(dataDir, key);
107	
108	  try {
109	    if (!fs.statSync(srcPath).isFile()) return null;
110	  } catch {
111	    return null;
112	  }
113	
114	  return fs.readFileSync(srcPath);
115	}
116	
